// errExit prints the error and exits with code 1.
func errExit(msg string) {
	fmt.Fprintf(os.Stderr, "zk: error: %s\n", msg)
	os.Exit(1)
}

func warn(msg string) {
	fmt.Fprintf(os.Stderr, "zk: warning: %s\n", msg)
}

// commandDef describes a zk command, for help and flag parsing purposes.
type commandDef struct {
	name       string
	help       string
	short      map[byte]*flagDef
	long       map[string]*flagDef
	flagOrder  []*flagDef
	positional string // description of positional arguments
	// subcommands (only tag has these)
	subs map[string]*commandDef
	// If false, command needs a notebook (open/migrate).
	// init has its own path.
}

type flagDef struct {
	name     string
	short    byte
	hasValue bool
	repeats  bool
	// For --format: set of accepted values (empty = any string)
	enumValues []string
}

func main() {
	args := os.Args[1:]

	// Check if --version appears before any --help/-h
	for _, a := range args {
		if a == "--version" {
			fmt.Println("zk dev")
			return
		}
		if a == "--help" || a == "-h" {
			break
		}
	}

	// Check if --help/-h appears before any other real arg (handled below)
	parseAndRun(args)
}

// parseAndRun parses the argument list and dispatches to commands.
func parseAndRun(args []string) {
	// We need to implement a simple parser that matches kong-style behavior.
	// Global flags: --notebook-dir=PATH, -W/--working-dir=PATH, --no-input, -h/--help, --version
	// Commands: init, index, new, list, graph, edit, tag

	// Parsed state:
	var (
		globalHelp bool
		workingDir string
		notebookDir string
		hasNotebookDir bool
		// noInput bool // captured but unused after parse
	)

	// We first scan the args to extract global flags and identify the command.
	// Unknown flags before a known command are treated as errors.

	i := 0
	commandFound := ""
	var commandArgs []string

	// helper to look up global flag
	// The flag either consumes a value (for --working-dir/--notebook-dir) or not.

	// Walk until we find the command.
	for i < len(args) {
		a := args[i]
		if a == "--" {
			// rest are positional args
			i++
			if i < len(args) {
				commandFound = args[i]
				commandArgs = args[i+1:]
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			commandFound = a
			commandArgs = args[i+1:]
			break
		}
		// It's a flag.
		// Global flag parsing:
		name, val, hasVal := parseFlag(a)
		switch {
		case name == "h" || name == "help":
			globalHelp = true
			i++
		case name == "version":
			fmt.Println("zk dev")
			return
		case name == "notebook-dir":
			if hasVal {
				if val == "" {
					errExit("--notebook-dir requires a path argument")
				}
				notebookDir = val
				hasNotebookDir = true
			} else {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
				notebookDir = args[i]
				hasNotebookDir = true
			}
			i++
		case name == "W" || name == "working-dir":
			short := name == "W"
			if hasVal {
				if val == "" {
					if short {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
				workingDir = val
			} else {
				i++
				if i >= len(args) {
					if short {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
				workingDir = args[i]
			}
			i++
		case name == "no-input":
			// ignore value
			i++
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripEq(a)))
		}
	}

	// Resolve working dir
	cwd, _ := os.Getwd()
	if workingDir != "" {
		if !filepath.IsAbs(workingDir) {
			workingDir = filepath.Join(cwd, workingDir)
		}
		cwd = workingDir
	}
	// Strip trailing slashes (like /tmp/nb/)
	if len(cwd) > 1 && strings.HasSuffix(cwd, "/") {
		cwd = strings.TrimRight(cwd, "/")
	}

	// If notebook-dir env var is set, override unless explicit --notebook-dir
	if !hasNotebookDir {
		if env := os.Getenv("ZK_NOTEBOOK_DIR"); env != "" {
			notebookDir = env
			hasNotebookDir = true
		}
	}

	// Determine notebook path
	// First check if path is a real file/dir
	// If non-existent, print lstat warnings (match behavior)
	var notebookPath string
	if hasNotebookDir {
		// Print warnings if path doesn't exist (lstat fails)
		if _, err := os.Lstat(notebookDir); err != nil {
			// 2 or 3 warnings depending on conditions, approximate with 2
			warn(fmt.Sprintf("lstat %s: no such file or directory", notebookDir))
			warn(fmt.Sprintf("lstat %s: no such file or directory", notebookDir))
		}
		notebookPath = notebookDir
	} else {
		notebookPath = cwd
	}

	// If there's a command: dispatch with remaining args. Otherwise show help.
	if commandFound == "" {
		// No command: show main help unless opening the notebook fails
		// Try to find/open notebook for config loading
		if hasNotebookDir || !globalHelp {
			if nb, ok := discoverNotebook(notebookPath); ok {
				// Try to open (will fail with fts5 error)
				errExit(fmt.Sprintf("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5"))
				_ = nb
			}
		}
		fmt.Print(helpMain)
		return
	}

	// Handle commands
	switch commandFound {
	case "init":
		runInit(commandArgs, cwd, notebookPath, hasNotebookDir, globalHelp)
	case "index":
		runSimpleCmd("index", helpIndex, commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp, indexFlags)
	case "new":
		runSimpleCmd("new", helpNew, commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp, newFlags)
	case "list":
		runSimpleCmd("list", helpList, commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp, listFlags)
	case "graph":
		runGraph(commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp)
	case "edit":
		runSimpleCmd("edit", helpEdit, commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp, editFlags)
	case "tag":
		runTag(commandArgs, notebookPath, hasNotebookDir, cwd, globalHelp)
	default:
		errExit(fmt.Sprintf("unexpected argument %s", commandFound))
	}
}

// parseFlag takes "-W", "-W=x", "--x", "--x=y", "-abc"-style form.
// Returns name (without dashes), value, and whether =value was present.
// For short-combined "-Wh" we treat as -W with value "h".
func parseFlag(a string) (name string, value string, hasValue bool) {
	if strings.HasPrefix(a, "--") {
		rest := a[2:]
		if eq := strings.Index(rest, "="); eq >= 0 {
			return rest[:eq], rest[eq+1:], true
		}
		return rest, "", false
	}
	if strings.HasPrefix(a, "-") {
		rest := a[1:]
		if len(rest) == 0 {
			return "", "", false
		}
		// Single char flag
		if len(rest) == 1 {
			return rest, "", false
		}
		// -X=y
		if rest[1] == '=' {
			return string(rest[0]), rest[2:], true
		}
		// -Xy (combined - treat as -X with value y)
		return string(rest[0]), rest[1:], true
	}
	return a, "", false
}

func stripEq(a string) string {
	if i := strings.Index(a, "="); i >= 0 {
		a = a[:i]
	}
	if strings.HasPrefix(a, "--") {
		return a[2:]
	}
	if strings.HasPrefix(a, "-") {
		return a[1:]
	}
	return a
}

// discoverNotebook walks up from dir and returns the dir containing .zk.
func discoverNotebook(dir string) (string, bool) {
	cur := dir
	for {
		info, err := os.Stat(filepath.Join(cur, ".zk"))
		if err == nil && info.IsDir() {
			return cur, true
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return "", false
}

// runInit implements the init command.
func runInit(args []string, cwd string, notebookPath string, hasNotebookDir bool, globalHelp bool) {
	// Parse init args: optional --no-input (already consumed?), -h/--help, positional dir
	var dir string
	localHelp := globalHelp

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if !strings.HasPrefix(a, "-") {
			if dir != "" {
				errExit(fmt.Sprintf("unexpected argument %s", a))
			}
			dir = a
			i++
			continue
		}
		name, val, hasVal := parseFlag(a)
		switch {
		case name == "h" || name == "help":
			localHelp = true
			i++
		case name == "no-input":
			i++
		case name == "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
			_ = val
		case name == "W" || name == "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					short := name == "W"
					if short {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case name == "version":
			fmt.Println("zk dev")
			return
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripEq(a)))
		}
	}
	// remaining positional after --
	for ; i < len(args); i++ {
		a := args[i]
		if dir != "" {
			errExit(fmt.Sprintf("unexpected argument %s", a))
		}
		dir = a
	}

	if localHelp {
		fmt.Print(helpInit)
		return
	}

	// Open notebook (if cwd has one, it fails with fts5)
	// When --notebook-dir is set, it's an explicit path.
	// init in a subdir of a notebook: discovery finds parent, opens, fails.
	if _, found := discoverNotebook(notebookPath); found && !hasNotebookDir {
		errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
	}
	if hasNotebookDir {
		if _, err := os.Stat(filepath.Join(notebookPath, ".zk")); err == nil {
			errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
		}
	}

	// Resolve target directory
	if dir == "" {
		dir = cwd
	} else if !filepath.IsAbs(dir) {
		dir = filepath.Join(cwd, dir)
	}
	// Normalize: strip trailing /
	dir = filepath.Clean(dir)

	// Check if target has .zk
	if _, err := os.Stat(filepath.Join(dir, ".zk")); err == nil {
		errExit(fmt.Sprintf("init: a notebook already exists in %s", dir))
	}

	// Create structure
	if err := os.MkdirAll(filepath.Join(dir, ".zk", "templates"), 0755); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "config.toml"), configTemplate, 0644); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "templates", "default.md"), []byte(defaultNoteTemplate), 0644); err != nil {
		errExit(err.Error())
	}
	// Empty notebook.db
	if f, err := os.Create(filepath.Join(dir, ".zk", "notebook.db")); err != nil {
		errExit(err.Error())
	} else {
		f.Close()
	}

	// Print blank line to stderr (matching observed output which has empty line before migration error)
	fmt.Fprintln(os.Stderr)
	errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
}

// runGraph requires --format flag.
func runGraph(args []string, notebookPath string, hasNotebookDir bool, cwd string, globalHelp bool) {
	var format string
	var hasFormat bool
	localHelp := globalHelp

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if !strings.HasPrefix(a, "-") {
			// positional argument - acceptable
			i++
			continue
		}
		name, val, hasVal := parseFlag(a)
		switch {
		case name == "h" || name == "help":
			localHelp = true
			i++
		case name == "no-input":
			i++
		case name == "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
		case name == "W" || name == "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case name == "f" || name == "format":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--format: unexpected EOL")
				}
				val = args[i]
			}
			format = val
			hasFormat = true
			i++
		case name == "version":
			fmt.Println("zk dev")
			return
		default:
			// handle all the filter/sort flags that accept arguments
			if !consumeCommonFilterFlag(name, hasVal, args, &i) {
				errExit(fmt.Sprintf("unknown flag --%s", stripEq(a)))
			}
		}
	}

	if localHelp {
		fmt.Print(helpGraph)
		return
	}

	if !hasFormat {
		errExit("missing flags: --format=STRING")
	}
	if format != "json" {
		errExit(fmt.Sprintf("--format must be one of \"json\" but got %q", format))
	}

	// Need notebook
	notebookErrorExit(notebookPath, hasNotebookDir, cwd)
}

