// runSimpleCmd handles commands that take filter/format flags but all end up
// trying to open a notebook (which fails in our environment).
func runSimpleCmd(cmdName, helpText string, args []string, notebookPath string, hasNotebookDir bool, cwd string, globalHelp bool, knownFlags map[string]flagSpec) {
	localHelp := globalHelp
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			// rest are positional (allowed)
			break
		}
		if !strings.HasPrefix(a, "-") {
			// positional
			i++
			continue
		}
		name, _, hasVal := parseFlag(a)
		switch {
		case name == "h" || name == "help":
			localHelp = true
			i++
		case name == "no-input":
			i++
		case name == "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
		case name == "W" || name == "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case name == "version":
			fmt.Println("zk dev")
			return
		default:
			spec, ok := lookupFlag(knownFlags, name)
			if !ok {
				errExit(fmt.Sprintf("unknown flag --%s", stripEq(a)))
			}
			if spec.hasValue && !hasVal {
				i++
				if i >= len(args) {
					errExit(fmt.Sprintf("--%s: unexpected EOL", spec.canonical))
				}
			}
			i++
		}
	}

	if localHelp {
		fmt.Print(helpText)
		return
	}

	// Need a notebook
	notebookErrorExit(notebookPath, hasNotebookDir, cwd)
}

// notebookErrorExit emits the appropriate "cannot open notebook" error.
func notebookErrorExit(notebookPath string, hasNotebookDir bool, cwd string) {
	if hasNotebookDir {
		// Use notebookPath as given
		if _, err := os.Stat(filepath.Join(notebookPath, ".zk")); err == nil {
			errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
		}
		errExit(fmt.Sprintf("failed to open notebook: no notebook found in %s or a parent directory", notebookPath))
		return
	}
	if _, found := discoverNotebook(notebookPath); found {
		errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
	}
	errExit(fmt.Sprintf("failed to open notebook: no notebook found in %s or a parent directory", notebookPath))
}

// consumeCommonFilterFlag handles filter flags that consume a value.
func consumeCommonFilterFlag(name string, hasVal bool, args []string, i *int) bool {
	// Map short to long
	shortToLong := map[string]string{
		"i": "interactive",
		"n": "limit",
		"m": "match",
		"M": "match-strategy",
		"x": "exclude",
		"t": "tag",
		"l": "link-to",
		"L": "linked-by",
		"r": "recursive",
		"s": "sort",
		"q": "quiet",
		"P": "no-pager",
		"0": "delimiter0",
		"d": "delimiter",
		"p": "print-path",
	}
	canon := name
	if l, ok := shortToLong[name]; ok {
		canon = l
	}
	// Set of flags that take values
	withValue := map[string]bool{
		"limit": true, "match": true, "match-strategy": true, "exclude": true,
		"tag": true, "mention": true, "mentioned-by": true, "link-to": true,
		"no-link-to": true, "linked-by": true, "no-linked-by": true, "related": true,
		"max-distance": true, "created": true, "created-before": true, "created-after": true,
		"modified": true, "modified-before": true, "modified-after": true,
		"sort": true, "delimiter": true, "header": true, "footer": true, "format": true,
	}
	// boolean flags
	boolFlags := map[string]bool{
		"interactive": true, "recursive": true, "orphan": true, "tagless": true,
		"missing-backlink": true, "quiet": true, "no-pager": true, "delimiter0": true,
		"print-path": true,
	}
	if withValue[canon] {
		if !hasVal {
			(*i)++
			if *i >= len(args) {
				errExit(fmt.Sprintf("--%s: unexpected EOL", canon))
			}
		}
		(*i)++
		return true
	}
	if boolFlags[canon] {
		(*i)++
		return true
	}
	return false
}

