// parseFlag takes "-W", "-W=x", "--x", "--x=y", "-abc"-style form.
// Returns name (without dashes), value, and whether =value was present.
// For short-combined "-Wh" we treat as -W with value "h".
func parseFlag(a string) (name string, value string, hasValue bool) {
	if strings.HasPrefix(a, "--") {
		rest := a[2:]
		if eq := strings.Index(rest, "="); eq >= 0 {
			return rest[:eq], rest[eq+1:], true
		}
		return rest, "", false
	}
	if strings.HasPrefix(a, "-") {
		rest := a[1:]
		if len(rest) == 0 {
			return "", "", false
		}
		// Single char flag
		if len(rest) == 1 {
			return rest, "", false
		}
		// -X=y
		if rest[1] == '=' {
			return string(rest[0]), rest[2:], true
		}
		// -Xy (combined - treat as -X with value y)
		return string(rest[0]), rest[1:], true
	}
	return a, "", false
}

func stripEq(a string) string {
	if i := strings.Index(a, "="); i >= 0 {
		a = a[:i]
	}
	if strings.HasPrefix(a, "--") {
		return a[2:]
	}
	if strings.HasPrefix(a, "-") {
		return a[1:]
	}
	return a
}

// discoverNotebook walks up from dir and returns the dir containing .zk.
func discoverNotebook(dir string) (string, bool) {
	cur := dir
	for {
		info, err := os.Stat(filepath.Join(cur, ".zk"))
		if err == nil && info.IsDir() {
			return cur, true
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			break
		}
		cur = parent
	}
	return "", false
}

// runInit implements the init command.
func runInit(args []string, cwd string, notebookPath string, hasNotebookDir bool, globalHelp bool) {
	// Parse init args: optional --no-input (already consumed?), -h/--help, positional dir
	var dir string
	localHelp := globalHelp

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			break
		}
		if !strings.HasPrefix(a, "-") {
			if dir != "" {
				errExit(fmt.Sprintf("unexpected argument %s", a))
			}
			dir = a
			i++
			continue
		}
		name, val, hasVal := parseFlag(a)
		switch {
		case name == "h" || name == "help":
			localHelp = true
			i++
		case name == "no-input":
			i++
		case name == "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
			_ = val
		case name == "W" || name == "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					short := name == "W"
					if short {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case name == "version":
			fmt.Println("zk dev")
			return
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripEq(a)))
		}
	}
	// remaining positional after --
	for ; i < len(args); i++ {
		a := args[i]
		if dir != "" {
			errExit(fmt.Sprintf("unexpected argument %s", a))
		}
		dir = a
	}

	if localHelp {
		fmt.Print(helpInit)
		return
	}

	// Open notebook (if cwd has one, it fails with fts5)
	// When --notebook-dir is set, it's an explicit path.
	// init in a subdir of a notebook: discovery finds parent, opens, fails.
	if _, found := discoverNotebook(notebookPath); found && !hasNotebookDir {
		errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
	}
	if hasNotebookDir {
		if _, err := os.Stat(filepath.Join(notebookPath, ".zk")); err == nil {
			errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
		}
	}

	// Resolve target directory
	if dir == "" {
		dir = cwd
	} else if !filepath.IsAbs(dir) {
		dir = filepath.Join(cwd, dir)
	}
	// Normalize: strip trailing /
	dir = filepath.Clean(dir)

	// Check if target has .zk
	if _, err := os.Stat(filepath.Join(dir, ".zk")); err == nil {
		errExit(fmt.Sprintf("init: a notebook already exists in %s", dir))
	}

	// Create structure
	if err := os.MkdirAll(filepath.Join(dir, ".zk", "templates"), 0755); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "config.toml"), configTemplate, 0644); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "templates", "default.md"), []byte(defaultNoteTemplate), 0644); err != nil {
		errExit(err.Error())
	}
	// Empty notebook.db
	if f, err := os.Create(filepath.Join(dir, ".zk", "notebook.db")); err != nil {
		errExit(err.Error())
	} else {
		f.Close()
	}

	// Print blank line to stderr (matching observed output which has empty line before migration error)
	fmt.Fprintln(os.Stderr)
	errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
}

