// errExit prints an error to stderr and exits with code 1.
func errExit(msg string) {
	fmt.Fprintf(os.Stderr, "zk: error: %s\n", msg)
	os.Exit(1)
}

func warn(msg string) {
	fmt.Fprintf(os.Stderr, "zk: warning: %s\n", msg)
}

// Flag spec used by commands with multiple flags (list-style).
type flagSpec struct {
	canonical string
	short     string
	hasValue  bool
}

func buildFlagSet(specs []flagSpec) map[string]flagSpec {
	m := map[string]flagSpec{}
	for _, s := range specs {
		m[s.canonical] = s
		if s.short != "" {
			m[s.short] = s
		}
	}
	return m
}

// Global flag info
type globalInfo struct {
	workingDir     string
	hasWorkingDir  bool
	notebookDir    string
	hasNotebookDir bool
	// parsed index map
}

// parseFlag parses a single "-X", "-Xvalue", "-X=value", "--name", "--name=value".
// It returns: name (short char or long name without dashes), value, hasValue.
func parseFlag(a string) (name string, value string, hasValue bool) {
	if strings.HasPrefix(a, "--") {
		rest := a[2:]
		if eq := strings.Index(rest, "="); eq >= 0 {
			return rest[:eq], rest[eq+1:], true
		}
		return rest, "", false
	}
	if strings.HasPrefix(a, "-") && len(a) > 1 {
		rest := a[1:]
		// Single char flag
		if len(rest) == 1 {
			return rest, "", false
		}
		if rest[1] == '=' {
			return string(rest[0]), rest[2:], true
		}
		// -Xvalue combined short option
		return string(rest[0]), rest[1:], true
	}
	return a, "", false
}

// flagName returns the flag name portion ("--foo" or "-f") without the value.
func flagName(a string) string {
	if i := strings.Index(a, "="); i >= 0 {
		a = a[:i]
	}
	return a
}

// preScanGlobals scans args to extract -W/--working-dir and --notebook-dir.
// It does NOT error on unknown flags (that comes later).
// It returns the info and the remaining args with globals stripped? No, we keep original.
func preScanGlobals(args []string) globalInfo {
	g := globalInfo{}
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			break
		}
		if !strings.HasPrefix(a, "-") {
			// Stop at first positional? Actually we continue scanning - subcommand may have its own flags.
			i++
			continue
		}
		name, val, hasVal := parseFlag(a)
		takesValue := false
		short := false
		switch name {
		case "W":
			takesValue = true
			short = true
		case "working-dir":
			takesValue = true
		case "notebook-dir":
			takesValue = true
		}
		if takesValue {
			if !hasVal {
				if i+1 >= len(args) {
					// Error handled in main parse; but we need to report here to match behavior
					if short {
						errExit("-W requires a path argument")
					}
					errExit(fmt.Sprintf("--%s requires a path argument", name))
				}
				val = args[i+1]
				i++
			} else {
				if val == "" {
					if short {
						errExit("-W requires a path argument")
					}
					errExit(fmt.Sprintf("--%s requires a path argument", name))
				}
			}
			switch name {
			case "W", "working-dir":
				g.workingDir = val
				g.hasWorkingDir = true
			case "notebook-dir":
				g.notebookDir = val
				g.hasNotebookDir = true
			}
			i++
			continue
		}
		// Heuristic: skip this flag and move on (we don't know if it needs a value)
		// But for the prescan, we only care about -W/--working-dir/--notebook-dir.
		// Other flags may or may not have values - we don't consume extra args here.
		i++
	}
	return g
}

func main() {
	args := os.Args[1:]
	g := preScanGlobals(args)

	// Determine working dir
	cwd, _ := os.Getwd()
	if g.hasWorkingDir {
		wd := g.workingDir
		if !filepath.IsAbs(wd) {
			wd = filepath.Join(cwd, wd)
		}
		cwd = filepath.Clean(wd)
	}

	// Determine notebook path
	var nbPath string
	var nbFound bool
	if g.hasNotebookDir {
		nbPath = g.notebookDir
		// Emit warnings if path doesn't exist (~2 warnings for --notebook-dir path)
		if _, err := os.Lstat(nbPath); err != nil {
			warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
			warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
			nbFound = false
		} else {
			// Check if it contains a notebook
			if _, err := os.Stat(filepath.Join(nbPath, ".zk")); err == nil {
				nbFound = true
			} else {
				nbFound = false
			}
		}
	} else {
		// Use environment variable ZK_NOTEBOOK_DIR if set
		if env := os.Getenv("ZK_NOTEBOOK_DIR"); env != "" {
			nbPath = env
			if _, err := os.Lstat(nbPath); err != nil {
				warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
				warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
				warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
				nbFound = false
			} else if _, err := os.Stat(filepath.Join(nbPath, ".zk")); err == nil {
				nbFound = true
			}
		} else {
			// Walk up from cwd
			nbPath = cwd
			if g.hasWorkingDir {
				if _, err := os.Lstat(nbPath); err != nil {
					warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
					warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
					warn(fmt.Sprintf("lstat %s: no such file or directory", nbPath))
				}
			}
			if p, ok := discoverNotebook(cwd); ok {
				nbPath = p
				nbFound = true
			}
		}
	}

	// If notebook found, try to open it (always fails with FTS5 error in our env)
	if nbFound {
		errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
	}

	// No notebook. Now parse args normally and dispatch.
	runWithoutNotebook(args, cwd, nbPath, g.hasNotebookDir)
}

// discoverNotebook walks up from dir looking for .zk.
func discoverNotebook(dir string) (string, bool) {
	cur := dir
	for {
		if fi, err := os.Stat(filepath.Join(cur, ".zk")); err == nil && fi.IsDir() {
			return cur, true
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			return "", false
		}
		cur = parent
	}
}

// runWithoutNotebook performs the standard parse with no notebook available.
// It processes --help, --version, subcommand dispatch, and various errors.
func runWithoutNotebook(args []string, cwd string, nbPath string, hasNotebookDir bool) {
	// Scan args to find:
	// - First unknown flag (error)
	// - First --help / --version
	// - First positional (subcommand)
	// - Whether --no-input, etc.
	// Also find any parse errors for known flags needing values.

	cmdIdx := -1
	helpSeenIdx := -1
	versionSeenIdx := -1

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			// Following is command + args
			if i+1 < len(args) {
				cmdIdx = i + 1
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			cmdIdx = i
			break
		}
		name, val, hasVal := parseFlag(a)
		takesValue := false
		short := false
		switch name {
		case "W":
			takesValue = true
			short = true
		case "working-dir":
			takesValue = true
		case "notebook-dir":
			takesValue = true
		case "h", "help":
			if helpSeenIdx < 0 && (versionSeenIdx < 0 || i < versionSeenIdx) {
				helpSeenIdx = i
			}
			if helpSeenIdx < 0 {
				helpSeenIdx = i
			}
			i++
			continue
		case "version":
			if versionSeenIdx < 0 {
				versionSeenIdx = i
			}
			i++
			continue
		case "no-input":
			i++
			continue
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
		_ = val
		if takesValue {
			if !hasVal {
				i++
				if i >= len(args) {
					if short {
						errExit("-W requires a path argument")
					}
					errExit(fmt.Sprintf("--%s requires a path argument", name))
				}
			}
			i++
			continue
		}
	}

	// Decide: version vs help, based on first position seen
	if versionSeenIdx >= 0 && (helpSeenIdx < 0 || versionSeenIdx < helpSeenIdx) && cmdIdx < 0 {
		fmt.Println("zk dev")
		return
	}

	if cmdIdx < 0 {
		// No command: show help (if --help) or just show help (default when no command)
		fmt.Print(helpMain)
		return
	}

	cmd := args[cmdIdx]
	rest := args[cmdIdx+1:]

	// Handle global --version/--help before subcommand
	// If --version was seen before subcommand, print version
	if versionSeenIdx >= 0 && versionSeenIdx < cmdIdx && (helpSeenIdx < 0 || versionSeenIdx < helpSeenIdx) {
		fmt.Println("zk dev")
		return
	}
	if helpSeenIdx >= 0 && helpSeenIdx < cmdIdx && (versionSeenIdx < 0 || helpSeenIdx < versionSeenIdx) {
		fmt.Print(helpMain)
		return
	}

	// If helpSeen was at global level before subcommand didn't fire - continue to subcommand dispatch.
	// Whether --help was passed globally before command is propagated to command.

	switch cmd {
	case "init":
		runInit(rest, cwd, nbPath, hasNotebookDir, helpSeenIdx >= 0)
	case "index":
		runListish(rest, helpIndex, indexFlags, helpSeenIdx >= 0, nbPath, hasNotebookDir, cwd, false, "", false)
	case "new":
		runListish(rest, helpNew, newFlags, helpSeenIdx >= 0, nbPath, hasNotebookDir, cwd, false, "", false)
	case "list":
		runListish(rest, helpList, listFlags, helpSeenIdx >= 0, nbPath, hasNotebookDir, cwd, false, "", false)
	case "graph":
		runListish(rest, helpGraph, graphFlags, helpSeenIdx >= 0, nbPath, hasNotebookDir, cwd, true, "format", true)
	case "edit":
		runListish(rest, helpEdit, editFlags, helpSeenIdx >= 0, nbPath, hasNotebookDir, cwd, false, "", false)
	case "tag":
		runTag(rest, nbPath, hasNotebookDir, cwd, helpSeenIdx >= 0)
	default:
		errExit(fmt.Sprintf("unexpected argument %s", cmd))
	}
}

func stripDashes(s string) string {
	s = strings.TrimPrefix(s, "--")
	s = strings.TrimPrefix(s, "-")
	return s
}

func runInit(args []string, cwd string, nbPath string, hasNotebookDir bool, globalHelp bool) {
	var dir string
	var dirSet bool
	localHelp := globalHelp
	versionSeenIdx := -1
	helpSeenIdxLocal := -1
	if globalHelp {
		helpSeenIdxLocal = 0
	}
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			// positional follows
			for ; i < len(args); i++ {
				aa := args[i]
				if dirSet {
					errExit(fmt.Sprintf("unexpected argument %s", aa))
				}
				dir = aa
				dirSet = true
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			if dirSet {
				errExit(fmt.Sprintf("unexpected argument %s", a))
			}
			dir = a
			dirSet = true
			i++
			continue
		}
		name, _, hasVal := parseFlag(a)
		switch name {
		case "h", "help":
			localHelp = true
			if helpSeenIdxLocal < 0 {
				helpSeenIdxLocal = i + 1
			}
			i++
		case "no-input":
			i++
		case "W", "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
		case "version":
			if versionSeenIdx < 0 {
				versionSeenIdx = i + 1
			}
			i++
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
	}

	// version precedence
	if versionSeenIdx >= 0 && (helpSeenIdxLocal < 0 || versionSeenIdx < helpSeenIdxLocal) {
		fmt.Println("zk dev")
		return
	}
	if localHelp {
		fmt.Print(helpInit)
		return
	}

	// Resolve target directory
	if dir == "" {
		dir = cwd
	} else if !filepath.IsAbs(dir) {
		dir = filepath.Join(cwd, dir)
	}
	dir = filepath.Clean(dir)

	// Check if target has .zk
	if _, err := os.Stat(filepath.Join(dir, ".zk")); err == nil {
		errExit(fmt.Sprintf("init: a notebook already exists in %s", dir))
	}

	// Create structure
	if err := os.MkdirAll(filepath.Join(dir, ".zk", "templates"), 0755); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "config.toml"), configTemplate, 0644); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "templates", "default.md"), []byte(defaultNoteTemplate), 0644); err != nil {
		errExit(err.Error())
	}
	if f, err := os.Create(filepath.Join(dir, ".zk", "notebook.db")); err != nil {
		errExit(err.Error())
	} else {
		f.Close()
	}

	// Print blank line then the FTS5 error (matching observed behavior)
	fmt.Fprintln(os.Stderr)
	errExit("failed to open notebook: failed to migrate the database: database migration failed: no such module: fts5")
}

// runListish handles list, new, edit, index, graph.
// requireFlag is the name of a required flag (empty if none).
// enumFlag if non-empty means the flag must match enumValues (accepted). We'll hard-code for graph.
func runListish(args []string, helpText string, known map[string]flagSpec, globalHelp bool, nbPath string, hasNotebookDir bool, cwd string, hasRequired bool, requiredName string, requiredMustBeJSON bool) {
	localHelp := globalHelp
	versionSeenIdx := -1
	helpSeenIdxLocal := -1
	if globalHelp {
		helpSeenIdxLocal = 0
	}

	var requiredValue string
	var requiredSeen bool

	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			// Rest are positional (path args) - allowed
			for ; i < len(args); i++ {
				_ = args[i]
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			// positional (path argument) - allowed
			i++
			continue
		}
		name, val, hasVal := parseFlag(a)
		switch name {
		case "h", "help":
			localHelp = true
			if helpSeenIdxLocal < 0 {
				helpSeenIdxLocal = i + 1
			}
			i++
			continue
		case "no-input":
			i++
			continue
		case "W", "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
			continue
		case "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
			continue
		case "version":
			if versionSeenIdx < 0 {
				versionSeenIdx = i + 1
			}
			i++
			continue
		}
		spec, ok := known[name]
		if !ok {
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
		if spec.hasValue {
			if !hasVal {
				i++
				if i >= len(args) {
					errExit(fmt.Sprintf("--%s: unexpected EOL", spec.canonical))
				}
				val = args[i]
			}
			if hasRequired && spec.canonical == requiredName {
				requiredValue = val
				requiredSeen = true
			}
		}
		i++
	}

	// version precedence
	if versionSeenIdx >= 0 && (helpSeenIdxLocal < 0 || versionSeenIdx < helpSeenIdxLocal) {
		fmt.Println("zk dev")
		return
	}
	if localHelp {
		fmt.Print(helpText)
		return
	}

	if hasRequired && !requiredSeen {
		errExit(fmt.Sprintf("missing flags: --%s=STRING", requiredName))
	}
	if hasRequired && requiredMustBeJSON && requiredValue != "json" {
		errExit(fmt.Sprintf("--%s must be one of \"json\" but got %q", requiredName, requiredValue))
	}

	// need a notebook - but we already know there isn't one (main bailed out if there was)
	notebookErrorExit(nbPath, hasNotebookDir)
}

func runTag(args []string, nbPath string, hasNotebookDir bool, cwd string, globalHelp bool) {
	// Parse flags until we see a positional (subcommand name) or end
	localHelp := globalHelp
	versionSeenIdx := -1
	helpSeenIdxLocal := -1
	if globalHelp {
		helpSeenIdxLocal = 0
	}
	var sub string
	var subArgs []string
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			i++
			if i < len(args) {
				sub = args[i]
				subArgs = args[i+1:]
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			sub = a
			subArgs = args[i+1:]
			break
		}
		name, _, hasVal := parseFlag(a)
		switch name {
		case "h", "help":
			localHelp = true
			if helpSeenIdxLocal < 0 {
				helpSeenIdxLocal = i + 1
			}
			i++
		case "no-input":
			i++
		case "W", "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
		case "version":
			if versionSeenIdx < 0 {
				versionSeenIdx = i + 1
			}
			i++
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
	}

	if versionSeenIdx >= 0 && (helpSeenIdxLocal < 0 || versionSeenIdx < helpSeenIdxLocal) && sub == "" {
		fmt.Println("zk dev")
		return
	}

	if sub == "" {
		if localHelp {
			fmt.Print(helpTag)
			return
		}
		notebookErrorExit(nbPath, hasNotebookDir)
		return
	}
	if sub != "list" {
		errExit(fmt.Sprintf("unexpected argument %s", sub))
	}
	runListish(subArgs, helpTagList, tagListFlags, localHelp, nbPath, hasNotebookDir, cwd, false, "", false)
}

