// Flag spec used by commands with multiple flags (list-style).
type flagSpec struct {
	canonical string
	short     string
	hasValue  bool
}

func buildFlagSet(specs []flagSpec) map[string]flagSpec {
	m := map[string]flagSpec{}
	for _, s := range specs {
		m[s.canonical] = s
		if s.short != "" {
