// discoverNotebook walks up from dir looking for .zk.
func discoverNotebook(dir string) (string, bool) {
	cur := dir
	for {
		if fi, err := os.Stat(filepath.Join(cur, ".zk")); err == nil && fi.IsDir() {
			return cur, true
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			return "", false
		}
		cur = parent
	}
}

// runWithoutNotebook performs the standard parse with no notebook available.
