// parseFlag parses a single "-X", "-Xvalue", "-X=value", "--name", "--name=value".
// It returns: name (short char or long name without dashes), value, hasValue.
func parseFlag(a string) (name string, value string, hasValue bool) {
	if strings.HasPrefix(a, "--") {
		rest := a[2:]
		if eq := strings.Index(rest, "="); eq >= 0 {
			return rest[:eq], rest[eq+1:], true
		}
		return rest, "", false
	}
	if strings.HasPrefix(a, "-") && len(a) > 1 {
		rest := a[1:]
		// Single char flag
		if len(rest) == 1 {
			return rest, "", false
		}
		if rest[1] == '=' {
			return string(rest[0]), rest[2:], true
		}
		// -Xvalue combined short option
		return string(rest[0]), rest[1:], true
	}
	return a, "", false
}

// flagName returns the flag name portion ("--foo" or "-f") without the value.
func flagName(a string) string {
	if i := strings.Index(a, "="); i >= 0 {
		a = a[:i]
	}
	return a
}

// preScanGlobals scans args to extract -W/--working-dir and --notebook-dir.
