			}
			i++
			continue
		case "no-input":
			i++
			continue
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
		_ = val
		if takesValue {
			if !hasVal {
				i++
				if i >= len(args) {
					if short {
						errExit("-W requires a path argument")
					}
					errExit(fmt.Sprintf("--%s requires a path argument", name))
				}
			}
			i++
			continue
		}
	}

	// Decide: version vs help, based on first position seen
	if versionSeenIdx >= 0 && (helpSeenIdx < 0 || versionSeenIdx < helpSeenIdx) && cmdIdx < 0 {
		fmt.Println("zk dev")
		return
