			// positional follows
			for ; i < len(args); i++ {
				aa := args[i]
				if dirSet {
					errExit(fmt.Sprintf("unexpected argument %s", aa))
				}
				dir = aa
				dirSet = true
			}
			break
		}
		if !strings.HasPrefix(a, "-") {
			if dirSet {
				errExit(fmt.Sprintf("unexpected argument %s", a))
			}
			dir = a
			dirSet = true
			i++
			continue
		}
		name, _, hasVal := parseFlag(a)
		switch name {
		case "h", "help":
			localHelp = true
			if helpSeenIdxLocal < 0 {
				helpSeenIdxLocal = i + 1
			}
			i++
		case "no-input":
			i++
		case "W", "working-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					if name == "W" {
						errExit("-W requires a path argument")
					}
					errExit("--working-dir requires a path argument")
				}
			}
			i++
		case "notebook-dir":
			if !hasVal {
				i++
				if i >= len(args) {
					errExit("--notebook-dir requires a path argument")
				}
			}
			i++
		case "version":
			if versionSeenIdx < 0 {
				versionSeenIdx = i + 1
			}
			i++
		default:
			errExit(fmt.Sprintf("unknown flag --%s", stripDashes(flagName(a))))
		}
	}

	// version precedence
	if versionSeenIdx >= 0 && (helpSeenIdxLocal < 0 || versionSeenIdx < helpSeenIdxLocal) {
		fmt.Println("zk dev")
		return
	}
	if localHelp {
		fmt.Print(helpInit)
		return
	}

	// Resolve target directory
	if dir == "" {
		dir = cwd
	} else if !filepath.IsAbs(dir) {
		dir = filepath.Join(cwd, dir)
	}
	dir = filepath.Clean(dir)

	// Check if target has .zk
	if _, err := os.Stat(filepath.Join(dir, ".zk")); err == nil {
		errExit(fmt.Sprintf("init: a notebook already exists in %s", dir))
	}

	// Create structure
	if err := os.MkdirAll(filepath.Join(dir, ".zk", "templates"), 0755); err != nil {
		errExit(err.Error())
	}
	if err := os.WriteFile(filepath.Join(dir, ".zk", "config.toml"), configTemplate, 0644); err != nil {
